BEGIN;

CREATE EXTENSION IF NOT EXISTS pgcrypto;

DO $$
BEGIN
  CREATE TYPE document_status AS ENUM (
    'draft',
    'submitted',
    'in_review',
    'approved',
    'rejected'
  );
EXCEPTION
  WHEN duplicate_object THEN NULL;
END
$$;

DO $$
BEGIN
  CREATE TYPE review_decision_value AS ENUM (
    'approved',
    'rejected'
  );
EXCEPTION
  WHEN duplicate_object THEN NULL;
END
$$;

CREATE OR REPLACE FUNCTION set_row_updated_at()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  NEW.updated_at = CURRENT_TIMESTAMP;
  RETURN NEW;
END;
$$;

CREATE OR REPLACE FUNCTION enforce_document_status_transition()
RETURNS trigger
LANGUAGE plpgsql
AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    IF NEW.status IS DISTINCT FROM 'draft'::document_status THEN
      RAISE EXCEPTION 'new documents must start in draft'
        USING ERRCODE = '23514';
    END IF;

    RETURN NEW;
  END IF;

  IF NEW.status = OLD.status THEN
    RETURN NEW;
  END IF;

  IF (
    OLD.status = 'draft' AND NEW.status = 'submitted'
  ) OR (
    OLD.status = 'submitted' AND NEW.status = 'in_review'
  ) OR (
    OLD.status = 'in_review' AND NEW.status = 'approved'
  ) OR (
    OLD.status = 'in_review' AND NEW.status = 'rejected'
  ) THEN
    RETURN NEW;
  END IF;

  RAISE EXCEPTION 'invalid document status transition from % to %', OLD.status, NEW.status
    USING ERRCODE = '23514';
END;
$$;

CREATE TABLE IF NOT EXISTS documents (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  title varchar(255) NOT NULL,
  source_ref text NOT NULL,
  created_by text NOT NULL,
  mime_type text,
  checksum text,
  metadata jsonb,
  status document_status NOT NULL DEFAULT 'draft',
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  updated_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT documents_title_length_chk CHECK (char_length(title) BETWEEN 1 AND 255),
  CONSTRAINT documents_source_ref_not_blank_chk CHECK (char_length(trim(source_ref)) > 0),
  CONSTRAINT documents_created_by_not_blank_chk CHECK (char_length(trim(created_by)) > 0),
  CONSTRAINT documents_mime_type_not_blank_chk CHECK (mime_type IS NULL OR char_length(trim(mime_type)) > 0),
  CONSTRAINT documents_checksum_not_blank_chk CHECK (checksum IS NULL OR char_length(trim(checksum)) > 0)
);

CREATE TABLE IF NOT EXISTS review_decisions (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  document_id uuid NOT NULL REFERENCES documents(id) ON DELETE CASCADE,
  decision review_decision_value NOT NULL,
  notes text,
  reviewer_user_id text NOT NULL,
  decided_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT review_decisions_one_per_document_uq UNIQUE (document_id),
  CONSTRAINT review_decisions_reviewer_user_id_not_blank_chk CHECK (char_length(trim(reviewer_user_id)) > 0)
);

CREATE TABLE IF NOT EXISTS audit_events (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  entity_type text NOT NULL,
  entity_id uuid NOT NULL,
  action text NOT NULL,
  actor_user_id text,
  event_payload jsonb,
  occurred_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  request_id text NOT NULL,
  CONSTRAINT audit_events_entity_type_not_blank_chk CHECK (char_length(trim(entity_type)) > 0),
  CONSTRAINT audit_events_action_not_blank_chk CHECK (char_length(trim(action)) > 0),
  CONSTRAINT audit_events_request_id_not_blank_chk CHECK (char_length(trim(request_id)) > 0),
  CONSTRAINT audit_events_actor_user_id_not_blank_chk CHECK (actor_user_id IS NULL OR char_length(trim(actor_user_id)) > 0)
);

CREATE TABLE IF NOT EXISTS idempotency_records (
  id uuid PRIMARY KEY DEFAULT gen_random_uuid(),
  idempotency_key text NOT NULL,
  request_fingerprint text NOT NULL,
  route_key text NOT NULL,
  resource_type text,
  resource_id uuid,
  response_status_code integer,
  response_body jsonb,
  created_at timestamptz NOT NULL DEFAULT CURRENT_TIMESTAMP,
  CONSTRAINT idempotency_records_route_key_not_blank_chk CHECK (char_length(trim(route_key)) > 0),
  CONSTRAINT idempotency_records_key_not_blank_chk CHECK (char_length(trim(idempotency_key)) > 0),
  CONSTRAINT idempotency_records_fingerprint_not_blank_chk CHECK (char_length(trim(request_fingerprint)) > 0),
  CONSTRAINT idempotency_records_resource_type_not_blank_chk CHECK (resource_type IS NULL OR char_length(trim(resource_type)) > 0),
  CONSTRAINT idempotency_records_response_status_code_chk CHECK (
    response_status_code IS NULL OR response_status_code BETWEEN 100 AND 599
  ),
  CONSTRAINT idempotency_records_route_key_key_uq UNIQUE (route_key, idempotency_key)
);

CREATE INDEX IF NOT EXISTS documents_status_created_at_idx
  ON documents (status, created_at DESC);

CREATE INDEX IF NOT EXISTS review_decisions_document_id_idx
  ON review_decisions (document_id);

CREATE INDEX IF NOT EXISTS audit_events_entity_idx
  ON audit_events (entity_type, entity_id, occurred_at DESC);

CREATE INDEX IF NOT EXISTS audit_events_request_id_idx
  ON audit_events (request_id);

CREATE INDEX IF NOT EXISTS idempotency_records_created_at_idx
  ON idempotency_records (created_at DESC);

DROP TRIGGER IF EXISTS documents_set_updated_at ON documents;
CREATE TRIGGER documents_set_updated_at
BEFORE UPDATE ON documents
FOR EACH ROW
EXECUTE FUNCTION set_row_updated_at();

DROP TRIGGER IF EXISTS documents_enforce_status_transition ON documents;
CREATE TRIGGER documents_enforce_status_transition
BEFORE INSERT OR UPDATE OF status ON documents
FOR EACH ROW
EXECUTE FUNCTION enforce_document_status_transition();

COMMIT;
