const DOCUMENT_STATUSES = Object.freeze([
  'draft',
  'submitted',
  'in_review',
  'approved',
  'rejected'
]);

const INITIAL_DOCUMENT_STATUS = 'draft';

const TERMINAL_DOCUMENT_STATUSES = Object.freeze([
  'approved',
  'rejected'
]);

const ALLOWED_DOCUMENT_TRANSITIONS = Object.freeze({
  draft: Object.freeze(['submitted']),
  submitted: Object.freeze(['in_review']),
  in_review: Object.freeze(['approved', 'rejected']),
  approved: Object.freeze([]),
  rejected: Object.freeze([])
});

const ALLOWED_DOCUMENT_TRANSITION_PATHS = Object.freeze([
  'draft->submitted',
  'submitted->in_review',
  'in_review->approved',
  'in_review->rejected'
]);

function buildForbiddenDocumentTransitions() {
  const forbiddenTransitions = [];

  for (const fromStatus of DOCUMENT_STATUSES) {
    for (const toStatus of DOCUMENT_STATUSES) {
      if (fromStatus === toStatus) {
        continue;
      }

      if (!ALLOWED_DOCUMENT_TRANSITIONS[fromStatus].includes(toStatus)) {
        forbiddenTransitions.push(`${fromStatus}->${toStatus}`);
      }
    }
  }

  return forbiddenTransitions;
}

const FORBIDDEN_DOCUMENT_TRANSITIONS = Object.freeze(
  buildForbiddenDocumentTransitions()
);

function isDocumentStatus(value) {
  return DOCUMENT_STATUSES.includes(value);
}

function assertDocumentStatus(value, label = 'document status') {
  if (!isDocumentStatus(value)) {
    throw new TypeError(
      `${label} must be one of ${DOCUMENT_STATUSES.join(', ')}`
    );
  }

  return value;
}

function isTerminalDocumentStatus(value) {
  return TERMINAL_DOCUMENT_STATUSES.includes(value);
}

function getNextAllowedDocumentStatuses(currentStatus) {
  if (!isDocumentStatus(currentStatus)) {
    return [];
  }

  return [...ALLOWED_DOCUMENT_TRANSITIONS[currentStatus]];
}

function isAllowedDocumentTransition(from, to) {
  if (!isDocumentStatus(from) || !isDocumentStatus(to)) {
    return false;
  }

  return ALLOWED_DOCUMENT_TRANSITIONS[from].includes(to);
}

module.exports = {
  DOCUMENT_STATUSES,
  INITIAL_DOCUMENT_STATUS,
  TERMINAL_DOCUMENT_STATUSES,
  ALLOWED_DOCUMENT_TRANSITIONS,
  ALLOWED_DOCUMENT_TRANSITION_PATHS,
  FORBIDDEN_DOCUMENT_TRANSITIONS,
  isDocumentStatus,
  assertDocumentStatus,
  isTerminalDocumentStatus,
  getNextAllowedDocumentStatuses,
  isAllowedDocumentTransition
};
