const {
  INITIAL_DOCUMENT_STATUS,
  isDocumentStatus
} = require('./documentLifecycle.js');

const DOCUMENT_TABLE = 'documents';

const DOCUMENT_REQUIRED_CREATE_FIELDS = Object.freeze([
  'title',
  'source_ref',
  'created_by'
]);

const DOCUMENT_OPTIONAL_CREATE_FIELDS = Object.freeze([
  'mime_type',
  'checksum',
  'metadata'
]);

const DOCUMENT_MUTABLE_METADATA_FIELDS = Object.freeze([
  'title',
  'source_ref',
  'mime_type',
  'checksum',
  'metadata'
]);

const DOCUMENT_IMMUTABLE_FIELDS = Object.freeze([
  'id',
  'status',
  'created_by',
  'created_at',
  'updated_at'
]);

const DOCUMENT_TIMESTAMP_FIELDS = Object.freeze([
  'created_at',
  'updated_at'
]);

const DOCUMENT_PERSISTED_FIELDS = Object.freeze([
  'id',
  'title',
  'source_ref',
  'created_by',
  'mime_type',
  'checksum',
  'metadata',
  'status',
  'created_at',
  'updated_at'
]);

function isPlainObject(value) {
  return value !== null && typeof value === 'object' && !Array.isArray(value);
}

function isNonBlankString(value) {
  return typeof value === 'string' && value.trim().length > 0;
}

function isTimestampValue(value) {
  return value instanceof Date || typeof value === 'string';
}

function isMutableDocumentField(fieldName) {
  return DOCUMENT_MUTABLE_METADATA_FIELDS.includes(fieldName);
}

function isImmutableDocumentField(fieldName) {
  return DOCUMENT_IMMUTABLE_FIELDS.includes(fieldName);
}

function hasRequiredDocumentCreateFields(input) {
  if (!isPlainObject(input)) {
    return false;
  }

  return DOCUMENT_REQUIRED_CREATE_FIELDS.every((fieldName) => {
    if (!Object.prototype.hasOwnProperty.call(input, fieldName)) {
      return false;
    }

    return isNonBlankString(input[fieldName]);
  });
}

function getDocumentCreateDefaults() {
  return {
    status: INITIAL_DOCUMENT_STATUS
  };
}

function sanitizeDocumentPatch(input) {
  if (!isPlainObject(input)) {
    return {};
  }

  const patch = {};

  for (const fieldName of DOCUMENT_MUTABLE_METADATA_FIELDS) {
    if (Object.prototype.hasOwnProperty.call(input, fieldName)) {
      patch[fieldName] = input[fieldName];
    }
  }

  return patch;
}

function isDocumentRecordShape(value) {
  if (!isPlainObject(value)) {
    return false;
  }

  if (!isNonBlankString(value.id)) {
    return false;
  }

  if (!isNonBlankString(value.title) || value.title.length > 255) {
    return false;
  }

  if (!isNonBlankString(value.source_ref)) {
    return false;
  }

  if (!isNonBlankString(value.created_by)) {
    return false;
  }

  if (
    value.mime_type !== undefined &&
    value.mime_type !== null &&
    !isNonBlankString(value.mime_type)
  ) {
    return false;
  }

  if (
    value.checksum !== undefined &&
    value.checksum !== null &&
    !isNonBlankString(value.checksum)
  ) {
    return false;
  }

  if (
    value.metadata !== undefined &&
    value.metadata !== null &&
    !isPlainObject(value.metadata)
  ) {
    return false;
  }

  if (!isDocumentStatus(value.status)) {
    return false;
  }

  if (!isTimestampValue(value.created_at) || !isTimestampValue(value.updated_at)) {
    return false;
  }

  return true;
}

module.exports = {
  DOCUMENT_TABLE,
  DOCUMENT_REQUIRED_CREATE_FIELDS,
  DOCUMENT_OPTIONAL_CREATE_FIELDS,
  DOCUMENT_MUTABLE_METADATA_FIELDS,
  DOCUMENT_IMMUTABLE_FIELDS,
  DOCUMENT_TIMESTAMP_FIELDS,
  DOCUMENT_PERSISTED_FIELDS,
  isMutableDocumentField,
  isImmutableDocumentField,
  hasRequiredDocumentCreateFields,
  getDocumentCreateDefaults,
  sanitizeDocumentPatch,
  isDocumentRecordShape
};
