const test = require('node:test');
const assert = require('node:assert/strict');
const path = require('node:path');

const lifecycle = require(path.resolve(
  __dirname,
  '../../../../src/src/domain/documents/model/documentLifecycle.js'
));

test('document status contract exposes only canonical lifecycle values', () => {
  assert.deepEqual(lifecycle.DOCUMENT_STATUSES, [
    'draft',
    'submitted',
    'in_review',
    'approved',
    'rejected'
  ]);

  assert.equal(lifecycle.INITIAL_DOCUMENT_STATUS, 'draft');
  assert.deepEqual(lifecycle.TERMINAL_DOCUMENT_STATUSES, [
    'approved',
    'rejected'
  ]);

  assert.equal(lifecycle.isDocumentStatus('draft'), true);
  assert.equal(lifecycle.isDocumentStatus('not_a_status'), false);
  assert.equal(lifecycle.isTerminalDocumentStatus('approved'), true);
  assert.equal(lifecycle.isTerminalDocumentStatus('rejected'), true);
  assert.equal(lifecycle.isTerminalDocumentStatus('submitted'), false);

  assert.equal(lifecycle.assertDocumentStatus('draft'), 'draft');
  assert.throws(
    () => lifecycle.assertDocumentStatus('not_a_status'),
    /document status must be one of/
  );
});

test('document transition contract exposes allowed and forbidden transitions explicitly', () => {
  assert.deepEqual(lifecycle.ALLOWED_DOCUMENT_TRANSITIONS, {
    draft: ['submitted'],
    submitted: ['in_review'],
    in_review: ['approved', 'rejected'],
    approved: [],
    rejected: []
  });

  assert.deepEqual(lifecycle.ALLOWED_DOCUMENT_TRANSITION_PATHS, [
    'draft->submitted',
    'submitted->in_review',
    'in_review->approved',
    'in_review->rejected'
  ]);

  assert.equal(lifecycle.isAllowedDocumentTransition('draft', 'submitted'), true);
  assert.equal(lifecycle.isAllowedDocumentTransition('submitted', 'in_review'), true);
  assert.equal(lifecycle.isAllowedDocumentTransition('in_review', 'approved'), true);
  assert.equal(lifecycle.isAllowedDocumentTransition('in_review', 'rejected'), true);

  assert.equal(lifecycle.isAllowedDocumentTransition('submitted', 'draft'), false);
  assert.equal(lifecycle.isAllowedDocumentTransition('draft', 'in_review'), false);
  assert.equal(lifecycle.isAllowedDocumentTransition('submitted', 'approved'), false);
  assert.equal(lifecycle.isAllowedDocumentTransition('approved', 'rejected'), false);
  assert.equal(lifecycle.isAllowedDocumentTransition('rejected', 'approved'), false);

  assert.deepEqual(lifecycle.getNextAllowedDocumentStatuses('draft'), ['submitted']);
