REQ_ROOT="$(cd "${SCRIPT_DIR}/../../../../" && pwd)"
MIGRATION_UP="${REQ_ROOT}/src/src/platform/db/migrations/0001_req_001_canonical_schema.sql"
ARTIFACT_DIR="${REQ_ROOT}/test/artifacts/db"
LOG_FILE="${ARTIFACT_DIR}/migration-smoke.log"
SCHEMA_REPORT="${ARTIFACT_DIR}/schema-check.txt"
DB_URL="${REQ001_TEST_DATABASE_URL:-${DATABASE_URL:-}}"

mkdir -p "${ARTIFACT_DIR}"
: > "${LOG_FILE}"

log() {
  printf '%s %s\n' "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$*" | tee -a "${LOG_FILE}"
}

fail() {
  log "FAIL: $*"
  exit 1
}

psql_exec() {
  psql "${DB_URL}" -v ON_ERROR_STOP=1 -X -q "$@"
}

query_value() {
  psql "${DB_URL}" -X -Atq -c "$1"
}

assert_eq() {
  local expected="$1"
  local actual="$2"
  local label="$3"

  if [[ "${actual}" != "${expected}" ]]; then
    fail "${label}: expected '${expected}' but got '${actual}'"
  fi

  log "PASS: ${label} = ${actual}"
}

if [[ -z "${DB_URL}" ]]; then
  fail "REQ001_TEST_DATABASE_URL or DATABASE_URL must be set"
fi

if ! command -v psql >/dev/null 2>&1; then
  fail "psql client is required on PATH"
fi

log "resetting public schema"
psql_exec <<'SQL'
DROP SCHEMA IF EXISTS public CASCADE;
CREATE SCHEMA public;
SQL

log "applying migration ${MIGRATION_UP}"
psql_exec -f "${MIGRATION_UP}"

assert_eq "1" "$(query_value "SELECT COUNT(*) FROM information_schema.tables WHERE table_schema = 'public' AND table_name = 'documents';")" "documents table exists"
