assert_eq "{draft,submitted,in_review,approved,rejected}" "$(query_value "SELECT enum_range(NULL::document_status)::text;")" "document_status enum"
assert_eq "{approved,rejected}" "$(query_value "SELECT enum_range(NULL::review_decision_value)::text;")" "review_decision_value enum"

assert_eq "1" "$(query_value "SELECT COUNT(*) FROM pg_proc WHERE proname = 'set_row_updated_at';")" "set_row_updated_at function exists"
